def _chain_conf(key, default=None):
    """A journey.* conf the chain reads at import (S3B_HIERARCHY_VERSION), from the lane's chain_conf_json."""
    return CHAIN_CONF.get(key, default)


def read_source(name):
    """silver's read_source: the ACTIVE_ROWS_V1 rule; READ_AS_OF reads every source as of the parity timestamp.
    An overridden (dev) lookup is read at its current version: it did not exist at any prod timestamp."""
    bare = name.replace("`", "")
    if bare in LOOKUP_OVERRIDES:
        return active_rows(spark.read.table(LOOKUP_OVERRIDES[bare]), name)
    # READ_AS_OF is resolved to a version: Delta refuses a timestamp after the latest commit of an unchanged table.
    reader = _contract.reader_as_of(spark, name, READ_AS_OF)
    return active_rows(reader.table(name), name)


def _n(name):
    """The chain reads one silver MV by logical name, the private OMOP->SNOMED crosswalk; the resolver keeps a copy."""
    if name != "journey_reference._snomed_concept_crosswalk":
        raise ValueError(f"mapping_chain reads no silver dataset other than the crosswalk: {name}")
    return CROSSWALK_TABLE



NULL_TOKEN = "~"


def _enc(col_or_lit):
    """Encode one part of a key: NULL becomes '~', anything else base64(trim(string)).
    base64 output contains neither ':' nor '~', so parts joined with ':' can only be
    read back one way and two different inputs can never produce the same key."""
    c = col_or_lit if isinstance(col_or_lit, Column) else F.lit(col_or_lit)
    s = F.trim(c.cast("string"))
    return F.when(c.isNull(), F.lit(NULL_TOKEN)).otherwise(F.base64(s.cast("binary")))


def stable_id(namespace, *cols):
    """patient_event_id / encounter_id minting: sha2 over encoded namespace + natural-key parts.
    namespace = fact kind + source feed. NEVER the target table name (promotion-safe)."""
    return F.sha2(F.concat_ws(":", _enc(namespace), *[_enc(c) for c in cols]), 256)


