SDI_BODY_SITE_RELATIONSHIPS = [("Has dir proc site", "omop_has_dir_proc_site"), ("Has proc site", "omop_has_proc_site"),
                               ("Has indir proc site", "omop_has_indir_proc_site")]


def _sdi_imaging_body_site(df):
    """SDI_IMAGING_BODY_SITE_V1: SNOMED body structure of the mapped examination concept via the OMOP procedure-site
    relationships, best relationship rank first, lowest site concept id on ties; _multiple marks a tie."""
    rank = F.when(F.col("relationship_id") == SDI_BODY_SITE_RELATIONSHIPS[0][0], F.lit(1))
    for i, (rel, _) in enumerate(SDI_BODY_SITE_RELATIONSHIPS[1:], start=2):
        rank = rank.when(F.col("relationship_id") == rel, F.lit(i))
    site = (read_source("3_lookup.omop.concept")
            .where((F.col("vocabulary_id") == "SNOMED") & F.col("invalid_reason").isNull())
            .select(F.col("concept_id").cast("bigint").alias("_sdi_site_id"), F.col("concept_code").alias("_sdi_site_code"),
                    F.col("concept_name").alias("_sdi_site_name")))
    rel = (read_source("3_lookup.omop.concept_relationship")
           .where(F.col("relationship_id").isin(*[r for r, _ in SDI_BODY_SITE_RELATIONSHIPS]) & F.col("invalid_reason").isNull())
           .select(F.col("concept_id_1").cast("bigint").alias("_sdi_exam_id"), F.col("concept_id_2").cast("bigint").alias("_sdi_site_id"),
                   rank.alias("_sdi_rank"))
           .join(site, "_sdi_site_id"))
    best = rel.groupBy("_sdi_exam_id").agg(F.min("_sdi_rank").alias("_sdi_rank"))
    pick = (rel.join(best, ["_sdi_exam_id", "_sdi_rank"])
            .groupBy("_sdi_exam_id", "_sdi_rank")
            .agg(F.min(F.struct("_sdi_site_id", "_sdi_site_code", "_sdi_site_name")).alias("_sdi_site"),
                 F.countDistinct("_sdi_site_id").alias("_sdi_sites")))
    method = F.when(F.col("_sdi_rank") == 1, F.lit(SDI_BODY_SITE_RELATIONSHIPS[0][1]))
    for i, (_, name) in enumerate(SDI_BODY_SITE_RELATIONSHIPS[1:], start=2):
        method = method.when(F.col("_sdi_rank") == i, F.lit(name))
    df = df.join(pick, F.col("exam_omop_concept_id") == F.col("_sdi_exam_id"), "left")
    return (df.withColumn("body_site_snomed_code", F.col("_sdi_site._sdi_site_code"))
              .withColumn("body_site_snomed_display", F.col("_sdi_site._sdi_site_name"))
              .withColumn("body_site_snomed_method",
                          F.when(F.col("_sdi_sites") > 1, F.concat(method, F.lit("_multiple"))).otherwise(method))
              .drop("_sdi_exam_id", "_sdi_rank", "_sdi_site", "_sdi_sites"))


class _S3Step:
    """One step of the S3 mapping chain: the axis it maps, the joins it adds to a plan and the function applying it."""

    def __init__(self, axis, joins, apply, allow_split=False):
        self.axis, self.joins, self.apply, self.allow_split = axis, joins, apply, allow_split


def _s3_lookup_step(axis, *args, allow_split=False, **kwargs):
    """A _s3_lookup_axis call as a step: two joins, three when it can split a row into components."""
    return _S3Step(axis, 3 if allow_split else 2,
                   lambda df: _s3_lookup_axis(df, axis, *args, allow_split=allow_split, **kwargs), allow_split)


def _s3_crosswalk_steps(axis):
    """SNOMED recovery from the OMOP id, then the OMOP standard-target check, for one axis.

    SILVER_RELEASE_20261025 item 1: the axes of vital_sign, clinical_score and condition_stage take the fixed
    recovery step; every other axis keeps the original one (Ben's decision: no plan change elsewhere).
    """
    recover = _s3_snomed_from_omop_v2 if axis in S3_SNOMED_FROM_OMOP_V2_AXES else _s3_snomed_from_omop
    return [_S3Step(axis, 1, lambda df: recover(df, axis)),
            _S3Step(axis, 1, lambda df: _s3_enforce_omop_standard_target(df, axis))]


def _icd10_dotted(code):
    """Dotless ICD-10 (A099) -> dotted (A09.9); dotted and three-character codes pass through unchanged."""
    c = F.upper(F.trim(code))
    return F.when(c.rlike(r"^[A-Z][0-9]{2}[0-9A-Z]"),
                  F.regexp_replace(c, r"^([A-Z][0-9]{2})([0-9A-Z])", "$1.$2")).otherwise(c)


def _s3_vocab_maps_to_step(axis, vocabulary, code_expr, fill, model_name):
    """One vocabulary lane as an S3 step (see the block comment above)."""
    system = f"urn:omop:vocab:{vocabulary}"
    if fill == "target":
        return _s3_lookup_step(axis, SRC_S3_VOCAB_MAPS_TO, system, code_expr, model_name=model_name)

    def fill_ids(df):
        # Equi-join on the code; the lookup is unique per (system, code), so rows never multiply.
        lk = (read_source(SRC_S3_VOCAB_MAPS_TO).where(F.col("source_coding_system") == system)
              .select(F.col("source_code").alias("_vm_code"), F.col("omop_concept_id").alias("_vm_target"),
                      F.col("omop_standard").alias("_vm_std"), F.col("source_concept_id").alias("_vm_source"),
                      F.col("mapping_rule_id").alias("_vm_rule"), F.col("mapping_version").alias("_vm_version")))
        df = df.join(lk, code_expr == F.col("_vm_code"), "left")
        # The axis' own map_rule_id/map_version describe the target mapping and stay as they are. The ids this
        # lane fills get their own provenance pair, set exactly when the lane supplied an id the row lacked.
        filled_target = F.lit(False)
        if fill == "omop":
            filled_target = F.col(f"{axis}_omop_concept_id").isNull() & (F.col("_vm_std") == "S") \
                & F.col("_vm_target").isNotNull()
            df = df.withColumn(f"{axis}_omop_concept_id", F.coalesce(
                F.col(f"{axis}_omop_concept_id"), F.when(F.col("_vm_std") == "S", F.col("_vm_target"))))
        filled_source = F.col(f"{axis}_omop_source_concept_id").isNull() & F.col("_vm_source").isNotNull()
        df = df.withColumn("_vm_filled", filled_target | filled_source)
        df = df.withColumn(f"{axis}_omop_source_concept_id",
                           F.coalesce(F.col(f"{axis}_omop_source_concept_id"), F.col("_vm_source")))
        prior_rule = (F.col(f"{axis}_omop_map_rule_id") if f"{axis}_omop_map_rule_id" in df.columns
                      else F.lit(None).cast("string"))
        prior_version = (F.col(f"{axis}_omop_map_version") if f"{axis}_omop_map_version" in df.columns
                         else F.lit(None).cast("string"))
        df = df.withColumn(f"{axis}_omop_map_rule_id", F.when(F.col("_vm_filled"), F.col("_vm_rule")).otherwise(prior_rule))
        df = df.withColumn(f"{axis}_omop_map_version", F.when(F.col("_vm_filled"), F.col("_vm_version")).otherwise(prior_version))
        return df.drop("_vm_code", "_vm_target", "_vm_std", "_vm_source", "_vm_rule", "_vm_version", "_vm_filled")
    return _S3Step(axis, 1, fill_ids)


INSR_W2_VOCAB_LANES = {
    "c_condition": ("condition", "condition", ("ICD10",), lambda: F.when(F.col("condition_source_system") == "http://hl7.org/fhir/sid/icd-10", _icd10_dotted(F.col("condition_source_code"))), "source_concept"),
    # BBR_FOLDIN_V1 (BBR-1): a condition row with a SNOMED concept and no OMOP id takes the concept itself when it
    # is standard, else its Maps-to standard. No ICD-10 fallback: a disagreeing ICD-derived OMOP id beside a SNOMED
    # target is ruled out (SCT_TRUD_V1 3.1); OMOP's router supplies that fallback.
    "c2_condition_omop": ("condition", "condition", ("SNOMED",), lambda: F.col("condition_snomed_code"), "omop"),
    "d_stage": ("condition_stage", "stage_diagnosis", ("ICD10", "ICD10CM"), lambda: F.when(F.col("stage_diagnosis_source_system") == "http://hl7.org/fhir/sid/icd-10", _icd10_dotted(F.col("stage_diagnosis_source_code"))), "target"),
    "f_vital_omop": ("vital_sign", "vital", ("SNOMED",), lambda: F.col("vital_snomed_code"), "omop"),
    "h_allergy": ("allergy_intolerance", "substance", ("SNOMED",), lambda: F.col("substance_snomed_code"), "omop"),
}


BBR_VITAL_SYNONYMS = (('^(pre )?(body )?weight( (measured|estimated|in kg|[(]kg[)]))?$', '27113001', 'Body weight'), ('^(pre )?height(/length)?( (measured|estimated|in cm|[(]metres[)]))?$', '50373000', 'Body height measure'), ('^(pre )?(bmi|body mass index)( (measured|estimated))?$', '60621009', 'Body mass index'))


BBR_VITAL_SYNONYM_RULE = 'vital:anthropometric_synonym_v1'


BBR_VITAL_LOINC_OMOP = {'27113001': (3025315, 3026600), '50373000': (3036277, 3035463), '60621009': (3038553, 36304833)}


def _vital_anthropometric_synonym(df):
    """BBR-3: map a vital row with no SNOMED code whose display is a weight / height / BMI synonym
    (BBR_VITAL_SYNONYMS), when it has no OMOP id either or only the concept's LOINC id (BBR_VITAL_LOINC_OMOP)."""
    display = F.regexp_replace(F.trim(F.regexp_replace(F.lower(F.col("vital_source_display")), r"\s+", " ")),
                               r"^zzz ?", "")
    code, term = F.lit(None).cast("string"), F.lit(None).cast("string")
    for regex, snomed, name in reversed(BBR_VITAL_SYNONYMS):   # the first pattern in the list wins
        code = F.when(display.rlike(regex), F.lit(snomed)).otherwise(code)
        term = F.when(display.rlike(regex), F.lit(name)).otherwise(term)
    basis = F.when(display.contains("estimated"), F.lit("estimated")).otherwise(F.lit("measured"))
    # The decision and its inputs are materialised first: a predicate over vital_snomed_code would re-resolve to the
    # new value after the first withColumn below and stop the later columns (Spark re-resolves on withColumn).
    df = (df.withColumn("_bbr_code", code).withColumn("_bbr_term", term).withColumn("_bbr_basis", basis)
            .withColumn("_bbr_loinc", F.lit(False)))
    for snomed, loinc_ids in BBR_VITAL_LOINC_OMOP.items():
        df = df.withColumn("_bbr_loinc", F.col("_bbr_loinc") | F.coalesce(
            (F.col("_bbr_code") == snomed) & F.col("vital_omop_concept_id").cast("bigint").isin(*loinc_ids), F.lit(False)))
    df = df.withColumn("_bbr_hit", F.col("vital_snomed_code").isNull() & F.col("_bbr_code").isNotNull()
                       & (F.col("vital_omop_concept_id").isNull() | F.col("_bbr_loinc")))
    hit = F.col("_bbr_hit")
    values = {
        "vital_snomed_code": F.col("_bbr_code"), "vital_snomed_display": F.col("_bbr_term"),
        "vital_target_system": F.lit(SNOMED_URI), "vital_target_code": F.col("_bbr_code"),
        "vital_target_display": F.col("_bbr_term"), "vital_map_method": F.lit("rule"),
        "vital_map_rule_id": F.concat(F.lit(BBR_VITAL_SYNONYM_RULE + ":"), F.col("_bbr_basis")),
        "vital_map_version": F.lit("BBR_FOLDIN_V1"), "vital_map_status": F.lit("mapped"),
        "vital_map_status_reason": F.lit(None).cast("string"), "vital_map_candidate_count": F.lit(1),
        "vital_map_competing_count": F.lit(1), "vital_map_component_index": F.lit(1),
        "vital_map_component_count": F.lit(1),
    }
    for column, value in values.items():
        df = df.withColumn(column, F.when(hit, value.cast(df.schema[column].dataType)).otherwise(F.col(column)))
    return df.drop("_bbr_code", "_bbr_term", "_bbr_basis", "_bbr_loinc", "_bbr_hit")


BBR_PATH_TEST_CODE_DISPLAY_SYSTEM = 'urn:barts:pathology:test:code_display'


BBR_PATH_TEST_DIMENSION_RULE = 'bbr:path_test_dimension_v1'


BBR_PATH_TEST_VARIANT_RULE = 'bbr:path_test_variant_v1'


BBR_PATH_TEST_VARIANT_RE = '(?i)int[\\s\\S]{0,3}ctl|internal control|(^|[^a-z])prp([^a-z]|$)|citrate'


def _path_test_code_display_step(df):
    """BBR-11/12b: apply the code|display additions rows to test rows with no code (and to dimension-rule keys)."""
    rank = Window.partitionBy("source_code").orderBy(
        F.when(F.col("status") == "PROPOSED", 0).otherwise(1), F.col("mapping_rule_id").asc_nulls_last(),
        F.col("target_code").asc_nulls_last())
    fields = ("target_coding_system", "target_code", "target_display", "omop_concept_id", "omop_standard",
              "mapping_method", "mapping_version", "hierarchy_version", "mapping_rule_id", "candidate_count",
              "mapping_cosine", "scoring_model", "mapping_status", "status_reason", "competing_count",
              "candidate_set_id", "rollup_levels")
    lookup = (read_source(SRC_S3_PATHOLOGY_TEST_ADDITIONS)
              .where((F.col("source_coding_system") == BBR_PATH_TEST_CODE_DISPLAY_SYSTEM)
                     & F.col("status").isin("PROPOSED", "UNMAPPED") & (F.col("component_index") == 1))
              .withColumn("_bbr_rn", F.row_number().over(rank)).where("_bbr_rn = 1")
              .select(F.col("source_code").alias("_bbr_key"), *[F.col(f).alias("_bbr_" + f) for f in fields]))
    key = F.concat_ws("|", F.col("test_source_code"),
                      F.lower(F.trim(F.regexp_replace(F.col("test_source_display"), r"\s+", " "))))
    df = df.join(lookup, key == F.col("_bbr_key"), "left")
    no_code = (F.col("test_snomed_code").isNull() & F.col("test_omop_concept_id").isNull()
               & F.col("test_target_code").isNull())
    # An embedding proposal with no SNOMED code (an OMOP-only LOINC candidate, e.g. TFC INR -> 3051593 at cosine 0.51)
    # gives way to the rule row, whose SNOMED target is asserted active in TRUD RF2 (SNOMED/TRUD precedence; review
    # fix 11-03: the dev re-resolve left 8,186 INR/APTR rows without SNOMED).
    proposal_without_snomed = (F.col("test_snomed_code").isNull()
                               & (F.coalesce(F.col("test_map_method"), F.lit("")) == "embedding_proposed"))
    # Materialised before any test_* column changes (a predicate over them would re-resolve after the first write).
    df = df.withColumn("_bbr_use", F.col("_bbr_key").isNotNull()
                       & (no_code | proposal_without_snomed
                          | (F.col("_bbr_mapping_rule_id") == BBR_PATH_TEST_DIMENSION_RULE)))
    use = F.coalesce(F.col("_bbr_use"), F.lit(False))
    is_snomed = F.col("_bbr_target_coding_system") == F.lit(SNOMED_URI)
    standard = F.col("_bbr_omop_standard") == "S"
    values = {
        "test_target_system": F.col("_bbr_target_coding_system"), "test_target_code": F.col("_bbr_target_code"),
        "test_target_display": F.col("_bbr_target_display"),
        "test_snomed_code": F.when(is_snomed, F.col("_bbr_target_code")),
        "test_snomed_display": F.when(is_snomed, F.col("_bbr_target_display")),
        "test_omop_concept_id": F.when(standard, F.col("_bbr_omop_concept_id")),
        "test_omop_source_concept_id": F.when(~standard, F.col("_bbr_omop_concept_id")),
        "test_map_method": F.col("_bbr_mapping_method"),
        "test_map_version": F.concat_ws("|", F.col("_bbr_mapping_version"), F.col("_bbr_hierarchy_version")),
        "test_map_rule_id": F.col("_bbr_mapping_rule_id"), "test_map_candidate_count": F.col("_bbr_candidate_count"),
        "test_map_cosine": F.col("_bbr_mapping_cosine"), "test_map_scoring_model": F.col("_bbr_scoring_model"),
        "test_map_status": F.col("_bbr_mapping_status"), "test_map_status_reason": F.col("_bbr_status_reason"),
        "test_map_competing_count": F.col("_bbr_competing_count"),
        "test_map_candidate_set_id": F.col("_bbr_candidate_set_id"), "test_map_component_index": F.lit(1),
        "test_map_component_count": F.lit(1), "test_map_rollup_levels": F.col("_bbr_rollup_levels"),
    }
    for column, value in values.items():
        df = df.withColumn(column, F.when(use, value.cast(df.schema[column].dataType)).otherwise(F.col(column)))
    return df.drop(*[c for c in df.columns if c.startswith("_bbr_")])


def _path_test_variant_guard(df):
    """BBR-12a: a QC or non-blood variant of a test (internal control, PRP, citrate) keeps no blood-test concept:
    its codes are cleared, map_status no_candidate, reason qc_or_nonblood_variant; the method stays (provenance)."""
    variant = F.coalesce(F.col("test_source_display").rlike(BBR_PATH_TEST_VARIANT_RE), F.lit(False))
    coded = (F.col("test_snomed_code").isNotNull() | F.col("test_omop_concept_id").isNotNull()
             | F.col("test_target_code").isNotNull())
    df = df.withColumn("_bbr_hit", variant & coded)   # materialised: the writes below clear what `coded` reads
    hit = F.col("_bbr_hit")
    for suffix in ("snomed_code", "snomed_display", "omop_concept_id", "omop_source_concept_id", "target_system",
                   "target_code", "target_display"):
        column = f"test_{suffix}"
        df = df.withColumn(column, F.when(hit, F.lit(None).cast(df.schema[column].dataType)).otherwise(F.col(column)))
    return (df.withColumn("test_map_status", F.when(hit, F.lit("no_candidate")).otherwise(F.col("test_map_status")))
              .withColumn("test_map_status_reason",
                          F.when(hit, F.lit("qc_or_nonblood_variant")).otherwise(F.col("test_map_status_reason")))
              .withColumn("test_map_rule_id",
                          F.when(hit, F.lit(BBR_PATH_TEST_VARIANT_RULE)).otherwise(F.col("test_map_rule_id")))
              .drop("_bbr_hit"))


def _s3_vocab_lane_steps(model_name, medication):
    """The enabled lanes of one model. medication=True returns only medication-axis lanes (they read
    _s3c_multum / _dmd_code, so they run before the _s3c_multum drop); False returns the others."""
    steps = []
    for model, axis, vocabularies, code, fill in INSR_W2_VOCAB_LANES.values():
        if model != model_name or (axis == "medication") != medication:
            continue
        for vocabulary in vocabularies:
            steps.append(_s3_vocab_maps_to_step(axis, vocabulary, code(), fill, model_name))
    if model_name == "condition_stage" and not medication:
        # P9_L2538b: 97,990 rows labelled ICD-10 carry ARIA adverse-event terms (Leukocytes, Neutrophils ...),
        # not codes. Relabel their source system so no ICD-10 consumer reads them as codes (no mapping: J33).
        not_icd = (F.col("stage_diagnosis_source_system") == "http://hl7.org/fhir/sid/icd-10") & \
                  ~F.upper(F.trim(F.col("stage_diagnosis_source_code"))).rlike(r"^[A-Z][0-9]{2}")
        steps.append(_S3Step("stage_diagnosis", 0, lambda df: df.withColumn(
            "stage_diagnosis_source_system",
            F.when(not_icd, F.lit("urn:barts:aria:adverse-event-term")).otherwise(F.col("stage_diagnosis_source_system")))))
    return steps


def _s3_mapping_steps(model_name):
    """The S3 mapping chain of a public clinical table, in the order _cross_qc_public applies it: deterministic
    lookups (they fill only an otherwise unmapped axis; each lookup is reduced to one explicitly ranked row before
    the left join), tier rescores, the OMOP crosswalk and standard-target checks, and imaging body site."""
    steps = []
    if model_name == "family_history":
        steps.append(_s3_lookup_step(
            "condition", SRC_S3_ICD10_MAP, "http://hl7.org/fhir/sid/icd-10",
            F.when(F.col("condition_source_system") == "http://hl7.org/fhir/sid/icd-10",
                   F.regexp_replace(F.upper(F.col("condition_source_code")), r"[^A-Z0-9]", "")),
            allow_split=True, model_name=model_name, replace_inferior=True))
    elif model_name == "imaging_exam":
        steps.append(_s3_lookup_step("exam", SRC_S3_NICIP_MAP, "urn:nhs:nicip", F.upper(F.trim(F.col("source_code"))), model_name=model_name))
        norm_display = F.lower(F.trim(F.regexp_replace(F.col("source_display"), r"\s+", " ")))
        steps.append(_s3_lookup_step("exam", SRC_S3C_IMAGING_NAME_MAP, "urn:cerner:radiology-exam",
                                     F.when(F.col("source_coding_system") == "urn:cerner:radiology-exam", norm_display), model_name=model_name, replace_inferior=True))
        steps.append(_s3_lookup_step("exam", SRC_S3C_IMAGING_NAME_MAP, "urn:sectra:examination-code",
                                     F.when(F.col("source_coding_system") == "urn:sectra:examination-code", norm_display), model_name=model_name, replace_inferior=True))
        steps.append(_s3_lookup_step("exam", SRC_S3B_IMAGING_LOCAL_MAP_V2, "urn:barts:imaging-local-exam",
                                     F.concat_ws("|", F.col("exam_source_system"), F.col("exam_source_code")), model_name=model_name))
    elif model_name == "allergy_intolerance":
        steps.append(_s3_lookup_step("substance", SRC_S3_ALLERGY_MAP, "urn:cerner:allergy-substance-text",
                                     F.lower(F.trim(F.regexp_replace(F.col("source_display"), r"\s+", " "))), model_name=model_name))
    elif model_name == "clinical_finding":
        # FINDING_AXIS_EVENTCD_V1: the finding axis is the Cerner EVENT_CD; mapped per distinct input (S3 domain).
        steps.append(_s3_lookup_step("finding", SRC_S3_FINDING_EVENT_CODE_MAP, "urn:cerner:code_value",
                                     F.when(F.col("finding_source_system") == "urn:cerner:code_value",
                                            F.col("finding_source_code")), model_name=model_name))
        steps.append(_s3_lookup_step("value", SRC_S3_VALUE_TEXT_MAP, "urn:cerner:nomenclature:answer-text",
                                     F.lower(F.trim(F.regexp_replace(F.coalesce(F.col("value_display"), F.col("value_text")), r"\s+", " "))), model_name=model_name))
    elif model_name == "condition_stage":
        steps.append(_s3_lookup_step("stage_group", SRC_S3_STAGE_MAP, "urn:barts:aria:stage-of-disease",
                                     F.lower(F.trim(F.regexp_replace(F.col("stage_of_disease"), r"\s+", " "))), model_name=model_name))
        steps.append(_s3_lookup_step(
            "stage_diagnosis", SRC_S3_ICD10_MAP, "http://hl7.org/fhir/sid/icd-10",
            F.when(F.col("stage_diagnosis_source_system") == "http://hl7.org/fhir/sid/icd-10",
                   F.regexp_replace(F.upper(F.col("stage_diagnosis_source_code")), r"[^A-Z0-9]", "")),
            model_name=model_name, replace_inferior=True))
    elif model_name == "condition":
        steps.append(_s3_lookup_step(
            "condition", SRC_S3_ICD10_MAP, "http://hl7.org/fhir/sid/icd-10",
            F.when(F.col("condition_source_system") == "http://hl7.org/fhir/sid/icd-10",
                   F.regexp_replace(F.upper(F.col("condition_source_code")), r"[^A-Z0-9]", "")),
            allow_split=True, model_name=model_name, replace_inferior=True))
    elif model_name == "procedure":
        steps.append(_s3_lookup_step(
            "procedure", SRC_S3_OPCS4_MAP, "http://fhir.hl7.org.uk/CodeSystem/OPCS-4",
            F.when(F.col("procedure_source_system") == "http://fhir.hl7.org.uk/CodeSystem/OPCS-4",
                   F.regexp_replace(F.upper(F.col("procedure_source_code")), r"[^A-Z0-9]", "")),
            allow_split=True, model_name=model_name, replace_inferior=True))
        steps.append(_s3_lookup_step(
            "procedure", SRC_S3_ENDOBASE_EXAM_MAP, "urn:barts:endobase:exam-type",
            F.when(F.col("source_object") == "endobase_exam",
                   F.lower(F.trim(F.regexp_replace(F.col("procedure_source_code"), r"\s+", " ")))), model_name=model_name))
        steps.append(_s3_lookup_step(
            "procedure", SRC_S3B_PROCEDURE_TEXT_MAP, "urn:barts:procedure-text",
            F.sha2(F.concat_ws("|",
                F.when(F.col("source_object") == "endobase_exam", F.lit("urn:barts:endobase-exam-type"))
                 .when(F.col("source_object").contains("implant"), F.lit("urn:barts:implant-primary-procedure"))
                 .otherwise(F.lit("urn:barts:surginet-procedure")),
                F.lower(F.trim(F.regexp_replace(F.col("procedure_source_display"), r"\s+", " ")))), 256),
            allow_split=True, model_name=model_name))
    elif model_name == "pathology_result":
        steps.append(_s3_lookup_step(
            "test", SRC_S3_PATHOLOGY_TEST_ADDITIONS, "urn:barts:pathology:test:cerner_testcode",
            F.when(F.lower(F.col("test_source_system")).contains("cerner-testcode"), F.col("test_source_code")), model_name=model_name))
        steps.append(_s3_lookup_step(
            "test", SRC_S3_PATHOLOGY_TEST_ADDITIONS, "urn:barts:pathology:test:tfc",
            F.when(F.lower(F.col("test_source_system")).contains("tfc"), F.col("test_source_code")), model_name=model_name))
    elif model_name == "specimen":
        # STM_SPECIMEN_TYPE_V1/silver-specimen: the only specimen-type mapping; keyed on the bronze namespace|code carried on the row.
        steps.append(_s3_lookup_step("specimen_type", SRC_S3_SPECIMEN_MAP_V2, "urn:barts:pathology:specimen-type",
                                     F.col("_specimen_type_lookup_key"), model_name=model_name))
    elif model_name == "presenting_complaint":
        steps.append(_S3Step("complaint", 0, lambda df: _s3_direct_axis(
            df, "complaint", F.col("source_coding_system"), F.col("source_code"), F.col("source_display"))))
        steps.append(_s3_lookup_step(
            "complaint", SRC_S3C_ECDS_COMPLAINT_MAP,
            "urn:cerner:nomenclature:ed-presenting-complaint",
            F.when(F.col("source_object").isin("ed_presenting_complaint", "ed_presenting_complaint_text"),
                   F.col("source_code")), model_name=model_name))
        steps.append(_s3_lookup_step(
            "complaint", SRC_S3B_COMPLAINT_TEXT_MAP, "urn:barts:complaint-text",
            F.when(F.col("source_object").isin("registration_reason_for_visit", "ed_presenting_complaint_text"),
                   F.col("complaint_text_normalised")), allow_split=True, model_name=model_name))
    elif model_name == "vital_sign":
        # BBR_FOLDIN_V1 (BBR-3): before the vocabulary lanes, so the OMOP lane fills the synonym rows' OMOP id.
        steps.append(_S3Step("vital", 0, _vital_anthropometric_synonym))
        steps.append(_s3_lookup_step(
            "unit", SRC_S3B_VITAL_UNIT_MAP, "urn:barts:vital:unit",
            F.lower(F.trim(F.regexp_replace(F.col("unit_source_value"), r"\s+", " "))),
            model_name=model_name,
        ))
        for _axis, _value in (
            ("method", F.col("method_display")),
            ("body_site", F.col("body_site_display")),
            ("interpretation", F.col("interpretation_display")),
        ):
            steps.append(_s3_lookup_step(
                _axis, SRC_S3B_MEASUREMENT_CONTEXT_MAP, f"urn:barts:vital:{_axis}",
                F.lower(F.trim(F.regexp_replace(_value, r"\s+", " "))),
                model_name=model_name,
            ))
    if model_name in ("medication_admin", "medication_order", "medication_dispense"):
        if model_name in ("medication_admin", "medication_order"):
            steps.append(_s3_lookup_step("medication", SRC_S3C_RXNORM_MULTUM_MAP, "urn:cerner:multum",
                                         F.col("_s3c_multum"), allow_split=False, model_name=model_name, replace_inferior=True))
            steps.append(_s3_lookup_step("medication", SRC_S3C_RXNORM_CLASS_MAP, "urn:cerner:multum:class",
                                         F.col("_s3c_multum"), allow_split=True, model_name=model_name, replace_inferior=True))
        if model_name == "medication_dispense":
            steps.append(_s3_lookup_step("medication", SRC_S3C_DMD_ID_MAP, "urn:nhs:dmd",
                                         F.col("_dmd_code"), model_name=model_name, replace_inferior=True))
        steps.append(_s3_lookup_step("medication", SRC_S3C_DMD_NAME_MAP, "urn:cerner:medication-text:strength",
                                     s3c_strength_key(F.col("medication_source_display")), allow_split=True, model_name=model_name))
        steps += _s3_vocab_lane_steps(model_name, medication=True)  # INSR_W2 W2.03
        steps.append(_S3Step("medication", 0, lambda df: df.drop("_s3c_multum") if "_s3c_multum" in df.columns else df))
        steps.append(_s3_lookup_step(
            "medication", SRC_S3B_MED_TEXT_MAP, "urn:cerner:medication-text",
            F.lower(F.trim(F.regexp_replace(F.col("medication_source_display"), r"\s+", " "))),
            allow_split=True, model_name=model_name))
    if model_name == "pathology_result":
        steps.append(_S3Step("test", 1, lambda df: _s3_apply_tier_rescore(
            df, "test", "bronze_pathology_test_auto_high",
            F.when(F.col("test_map_rule_id").contains("bronze_pathology_test_auto_high"), F.col("test_source_display")))))
        steps.append(_S3Step("test", 1, lambda df: _s3_apply_tier_rescore(
            df, "test", "bronze_pathology_test_auto_low",
            F.when(F.col("test_map_rule_id").contains("bronze_pathology_test_auto_low"), F.col("test_source_display")))))
        steps.append(_S3Step("result", 1, lambda df: _s3_apply_tier_rescore(df, "result", "bronze_pathology_result_auto", F.col("result_source_display"))))
        # BBR_FOLDIN_V1 (BBR-11, BBR-12): code|display additions after the rescores, then the variant guard.
        steps.append(_S3Step("test", 1, _path_test_code_display_step))
        steps.append(_S3Step("test", 0, _path_test_variant_guard))
    elif model_name == "procedure":
        steps.append(_S3Step("device", 1, lambda df: _s3_apply_tier_rescore(df, "device", "bronze_implant_layer5", F.col("implant_description"))))
    elif model_name == "device":
        steps.append(_S3Step("device", 1, lambda df: _s3_apply_tier_rescore(df, "device", "bronze_mediconnect_device", F.col("device_source_display"))))

        def unscorable_device(df):
            # A governed device-type mapping with a blank source display has no text to score: keep it as a rule.
            unscorable = ((F.col("device_map_method") == "embedding_proposed") &
                          (F.length(F.trim(F.coalesce(F.col("device_source_display"), F.lit("")))) == 0) &
                          F.col("device_target_code").isNotNull())
            return (df.withColumn("device_map_method", F.when(unscorable, F.lit("rule")).otherwise(F.col("device_map_method")))
                  .withColumn("device_map_rule_id", F.when(unscorable, F.lit("lookup.mediconnect_device_type_map:approved_without_text_score"))
                              .otherwise(F.col("device_map_rule_id")))
                  .withColumn("device_map_status_reason", F.when(unscorable, F.lit("blank source display; governed source-code mapping retained"))
                              .otherwise(F.col("device_map_status_reason"))))
        steps.append(_S3Step("device", 0, unscorable_device))
    steps += _s3_vocab_lane_steps(model_name, medication=False)  # INSR_W2 W2.03
    if model_name == 'clinical_score':  # INSR_W2 W2.13 score_event
        steps.append(_s3_lookup_step('score', "3_lookup.omop.insr_lane_score_event", "urn:insr:lane:score_event",
            F.concat_ws("|", F.col("score_source_system"), F.col("score_source_code")), model_name=model_name))
    for _old_name, (_axis, _source_only) in S3_PUBLIC_CODED_AXES.get(model_name, {}).items():
        if not _source_only:
            steps += _s3_crosswalk_steps(_axis)
    if model_name in ("pathology_result", "clinical_finding", "condition_stage"):
        _extra_axis = {"pathology_result":"result", "clinical_finding":"value", "condition_stage":"stage_group"}[model_name]
        steps += _s3_crosswalk_steps(_extra_axis)
    if model_name == "imaging_exam":  # SDI_IMAGING_BODY_SITE_V1: keyed on the mapped examination concept
        steps.append(_S3Step("exam", 2, _sdi_imaging_body_site))
    return steps
